import os
import socket
import threading
import logging
from datetime import datetime

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('ftp_server.log'),
        logging.StreamHandler()
    ]
)

# Authentication credentials
FTP_SERVER_ADDRESS = '127.0.0.1'
FTP_USERNAME = 'testuser'
FTP_PASSWORD = 'testpass'

class SimpleFTPServer:
    def __init__(self, host='127.0.0.1', port=2121):
        self.host = host
        self.port = port
        self.root_dir = './target'
        self.authenticated_users = set()
        os.makedirs(self.root_dir, exist_ok=True)
        self.server_socket = None
        self.running = False

    def start(self):
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind((self.host, self.port))
            self.server_socket.listen(1)
            self.running = True

            logging.info(f"FTP Server starting on {self.host}:{self.port}")
            logging.info(f"Target directory: {os.path.abspath(self.root_dir)}")
            logging.info(f"Authentication required: {FTP_USERNAME}/{FTP_PASSWORD}")

            # Handle only one session
            try:
                client_socket, addr = self.server_socket.accept()
                logging.info(f"Connection established from {addr}")
                self.handle_client(client_socket)
                client_socket.close()
            except Exception as e:
                logging.error(f"Error accepting connection: {e}")

        except socket.error as e:
            logging.error(f"Socket error during startup: {e}")
            return
        except Exception as e:
            logging.error(f"Unexpected error during startup: {e}")
            return
        finally:
            self.cleanup()

    def cleanup(self):
        self.running = False
        if self.server_socket:
            self.server_socket.close()
        logging.info("FTP server shutdown complete")

    def handle_client(self, client_socket):
        try:
            client_socket.send(b"220 Service ready\r\n")
            authenticated = False

            while self.running:
                try:
                    data = client_socket.recv(1024).decode('utf-8').strip()
                    if not data:
                        break

                    parts = data.split(' ')
                    command = parts[0].upper()

                    logging.info(f"Received command: {command}")

                    if command == 'USER':
                        username = parts[1] if len(parts) > 1 else ''
                        if username == FTP_USERNAME:
                            client_socket.send(b"331 User name okay, need password\r\n")
                            logging.info(f"User authentication attempt for: {username}")
                        else:
                            client_socket.send(b"530 Not logged in\r\n")
                            logging.warning(f"Failed authentication attempt for user: {username}")
                    elif command == 'PASS':
                        password = parts[1] if len(parts) > 1 else ''
                        if password == FTP_PASSWORD:
                            authenticated = True
                            client_socket.send(b"230 User logged in, proceed\r\n")
                            logging.info("User authenticated successfully")
                        else:
                            client_socket.send(b"530 Not logged in\r\n")
                            logging.warning("Failed authentication attempt")
                    elif command == 'PWD':
                        if not authenticated:
                            client_socket.send(b"530 Not logged in\r\n")
                            continue
                        client_socket.send(f'257 "{self.root_dir}" is current directory\r\n'.encode())
                        logging.info("PWD command executed")
                    elif command == 'LIST':
                        if not authenticated:
                            client_socket.send(b"530 Not logged in\r\n")
                            continue
                        self.list_directory(client_socket)
                        logging.info("LIST command executed")
                    elif command == 'RETR':
                        if not authenticated:
                            client_socket.send(b"530 Not logged in\r\n")
                            continue
                        filename = parts[1] if len(parts) > 1 else ''
                        self.retrieve_file(client_socket, filename)
                        logging.info(f"RETR command executed for file: {filename}")
                    elif command == 'STOR':
                        if not authenticated:
                            client_socket.send(b"530 Not logged in\r\n")
                            continue
                        filename = parts[1] if len(parts) > 1 else ''
                        self.store_file(client_socket, filename)
                        logging.info(f"STOR command executed for file: {filename}")
                    elif command == 'QUIT':
                        client_socket.send(b"221 Service closing control connection\r\n")
                        logging.info("Client disconnected")
                        break
                    else:
                        client_socket.send(b"502 Command not implemented\r\n")

                except socket.error as e:
                    logging.error(f"Socket error during communication: {e}")
                    break
                except Exception as e:
                    logging.error(f"Error processing command: {e}")
                    break

        except Exception as e:
            logging.error(f"Error in client handling: {e}")
        finally:
            try:
                client_socket.close()
            except:
                pass

    def list_directory(self, client_socket):
        try:
            files = os.listdir(self.root_dir)
            client_socket.send(b"150 File status okay; about to open data connection\r\n")

            for filename in files:
                filepath = os.path.join(self.root_dir, filename)
                stat = os.stat(filepath)
                size = stat.st_size
                mtime = datetime.fromtimestamp(stat.st_mtime)
                date_str = mtime.strftime("%b %d %H:%M")
                response = f"-rw-r--r-- 1 user group {size:>8} {date_str} {filename}\r\n"
                client_socket.send(response.encode())

            client_socket.send(b"226 Transfer complete\r\n")
        except Exception as e:
            logging.error(f"Error listing directory: {e}")
            client_socket.send(b"550 Failed to list directory\r\n")

    def retrieve_file(self, client_socket, filename):
        if not filename:
            client_socket.send(b"501 Syntax error in parameters\r\n")
            return

        filepath = os.path.join(self.root_dir, filename)
        try:
            with open(filepath, 'rb') as f:
                client_socket.send(b"150 Opening BINARY mode data connection\r\n")
                while True:
                    chunk = f.read(1024)
                    if not chunk:
                        break
                    client_socket.send(chunk)
                client_socket.send(b"226 Transfer complete\r\n")
            logging.info(f"File retrieved successfully: {filename}")
        except FileNotFoundError:
            client_socket.send(b"550 File not found\r\n")
            logging.warning(f"File not found during retrieval: {filename}")
        except Exception as e:
            logging.error(f"Error retrieving file {filename}: {e}")
            client_socket.send(b"550 Failed to retrieve file\r\n")

    def store_file(self, client_socket, filename):
        if not filename:
            client_socket.send(b"501 Syntax error in parameters\r\n")
            return

        filepath = os.path.join(self.root_dir, filename)
        try:
            client_socket.send(b"150 Opening BINARY mode data connection\r\n")
            with open(filepath, 'wb') as f:
                while True:
                    data = client_socket.recv(1024)
                    if not data:
                        break
                    f.write(data)
            client_socket.send(b"226 Transfer complete\r\n")
            logging.info(f"File stored successfully: {filename}")
        except Exception as e:
            logging.error(f"Error storing file {filename}: {e}")
            client_socket.send(b"550 Failed to store file\r\n")

def main():
    server = SimpleFTPServer()
    try:
        server.start()
    except KeyboardInterrupt:
        logging.info("Server interrupted by user")
    except Exception as e:
        logging.error(f"Server encountered unexpected error: {e}")
    finally:
        logging.info("Server exiting normally")

if __name__ == "__main__":
    main()

