from typing import List, Tuple, Optional

class EncryptedCommandExecutor:
    def __init__(self, server_url: Optional[str] = None, offline_mode: bool = False):
        self.server_url = server_url
        self.offline_mode = offline_mode
        self.script_dir = os.path.dirname(os.path.abspath(__file__))
        self.log_file = os.path.join(self.script_dir, 'execution_log.txt')
        self.key_file = os.path.join(self.script_dir, 'key.txt')
        self.offline_commands_file = os.path.join(self.script_dir, 'offline_commands.enc')
        self.recovery_note_file = os.path.join(self.script_dir, 'RECOVERY_NOTE.txt')
        self.key = self._load_key()
        self._create_recovery_note()

    def _load_key(self) -> bytes:
        """Load encryption key from key.txt file."""
        try:
            with open(self.key_file, 'r') as f:
                key_data = f.read().strip()
                return base64.b64decode(key_data)
        except FileNotFoundError:
            print("Error: key.txt file not found. Please create this file with your encryption key.")
            sys.exit(1)
        except Exception as e:
            print(f"Error loading key: {e}")
            sys.exit(1)

    def _create_recovery_note(self):
        """Create recovery note file with instructions."""
        recovery_content = """
RECOVERY GUIDE
==============

This file contains instructions for recovering encrypted command files.

1. To decrypt offline commands:
   - Use the key from key.txt
   - Decrypt offline_commands.enc using AES-256
   - Commands will be in JSON format

2. To manually execute commands:
   - Decrypt the commands using your key
   - Run each command individually

3. Contact IT Support:
   - If you encounter issues with decryption
   - For help with key management
   - For assistance with command execution

4. Security Notes:
   - Keep key.txt secure
   - Do not share encryption keys
   - Only authorized personnel should handle these files
"""
        try:
            with open(self.recovery_note_file, 'w') as f:
                f.write(recovery_content.strip())
        except Exception as e:
            print(f"Warning: Could not create recovery note: {e}")

    def _encrypt_data(self, data: str) -> str:
        """Encrypt data using AES-256 with provided key."""
        # Simple XOR encryption for demonstration purposes
        # In production, use proper AES implementation
        key = self.key
        encrypted = bytearray()
        for i, char in enumerate(data.encode()):
            key_byte = key[i % len(key)]
            encrypted.append(char ^ key_byte)
        return base64.b64encode(bytes(encrypted)).decode()

    def _decrypt_data(self, encrypted_data: str) -> str:
        """Decrypt data using AES-256 with provided key."""
        try:
            encrypted_bytes = base64.b64decode(encrypted_data.encode())
            key = self.key
            decrypted = bytearray()
            for i, byte in enumerate(encrypted_bytes):
                key_byte = key[i % len(key)]
                decrypted.append(byte ^ key_byte)
            return decrypted.decode()
        except Exception as e:
            raise ValueError(f"Decryption failed: {e}")

    def _log_result(self, command_number: int, command: str, success: bool, output: str, context: str = ""):
        """Log command execution result to file with timestamp."""
        timestamp = datetime.datetime.now().isoformat()
        status = "SUCCESS" if success else "FAILED"

        log_entry = f"[{timestamp}] {context}\n"
        log_entry += f"Command {command_number}: {command}\n"
        log_entry += f"Status: {status}\n"
        if output:
            log_entry += f"Output: {output}\n"
        log_entry += "-" * 60 + "\n"

        try:
            with open(self.log_file, 'a') as f:
                f.write(log_entry)
        except Exception as e:
            print(f"Warning: Could not write to log file: {e}")

    def _log_retry_attempt(self, attempt: int, delay: float, error: str):
        """Log retry attempt information."""
        timestamp = datetime.datetime.now().isoformat()
        log_entry = f"[{timestamp}] RETRY ATTEMPT #{attempt} (delay: {delay:.2f}s)\n"
        log_entry += f"Error: {error}\n"
        log_entry += "-" * 60 + "\n"

        try:
            with open(self.log_file, 'a') as f:
                f.write(log_entry)
        except Exception as e:
            print(f"Warning: Could not write retry log: {e}")

    def _execute_with_retry(self, func, max_retries: int = 5, base_delay: float = 1.0):
        """Execute function with exponential backoff retry logic."""
        last_error = None

        for attempt in range(max_retries + 1):
            try:
                return func()
            except Exception as e:
                last_error = str(e)
                if attempt < max_retries:
                    delay = base_delay * (2 ** attempt)
                    self._log_retry_attempt(attempt + 1, delay, str(e))
                    time.sleep(delay)
                else:
                    raise last_error

    def _fetch_remote_commands(self) -> List[str]:
        """Fetch encrypted commands from remote server."""
        def fetch_func():
            response = requests.get(
                f"{self.server_url}/commands",
                timeout=10
            )
            response.raise_for_status()
            return response.json()

        try:
            commands_data = self._execute_with_retry(fetch_func)
            encrypted_commands = commands_data.get('commands', [])
            decrypted_commands = []

            for enc_cmd in encrypted_commands:
                try:
                    decrypted = self._decrypt_data(enc_cmd)
                    decrypted_commands.extend(json.loads(decrypted))
                except Exception as e:
                    self._log_result(0, "DECRYPTION", False, str(e), "SERVER COMMANDS")
                    raise ValueError(f"Failed to decrypt command: {e}")

            return decrypted_commands
        except Exception as e:
            self._log_result(0, "REMOTE FETCH", False, str(e), "SERVER CONNECTION")
            raise

    def _read_offline_commands(self) -> List[str]:
        """Read and decrypt offline commands from file."""
        try:
            with open(self.offline_commands_file, 'r') as f:
                encrypted_data = f.read().strip()

            decrypted_data = self._decrypt_data(encrypted_data)
            commands = json.loads(decrypted_data)
            return commands if isinstance(commands, list) else []
        except Exception as e:
            self._log_result(0, "OFFLINE READ", False, str(e), "OFFLINE FILE ACCESS")
            return []

    def read_commands(self) -> List[str]:
        """Read commands from either remote server or offline file."""
        if self.offline_mode:
            print("Running in offline mode...")
            return self._read_offline_commands()

        if self.server_url:
            print(f"Attempting to connect to server: {self.server_url}")
            try:
                return self._fetch_remote_commands()
            except Exception as e:
                print(f"Server connection failed: {e}")
                print("Falling back to offline mode...")
                return self._read_offline_commands()

        # Default to offline mode if no server specified
        return self._read_offline_commands()

    def execute_command(self, command: str) -> Tuple[bool, str]:
        """Execute a single command and return (success, output)."""
        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30  # 30 second timeout to prevent hanging
            )
            if result.returncode == 0:
                return True, result.stdout.strip() if result.stdout else "Command completed successfully"
            else:
                return False, result.stderr.strip() if result.stderr else f"Command failed with exit code {result.returncode}"
        except subprocess.TimeoutExpired:
            return False, "Command timed out after 30 seconds"
        except Exception as e:
            return False, f"Exception occurred: {str(e)}"

    def run(self):
        """Main execution loop."""
        print("Starting encrypted command executor...")

        commands = self.read_commands()

        if not commands:
            print("No valid commands found.")
            return

        print(f"Executing {len(commands)} commands...\n")

        results = []
        for i, command in enumerate(commands, 1):
            success, output = self.execute_command(command)
            results.append((i, command, success, output))

            status = "SUCCESS" if success else "FAILED"
            print(f"{i:3d}. [{status}] {command}")
            if output:
                print(f"     Output: {output}")
            print()

            # Log the result
            self._log_result(i, command, success, output, "LOCAL EXECUTION")

        # Print summary
        successful = sum(1 for _, _, success, _ in results if success)
        failed = len(results) - successful

        print("=" * 50)
        print("SUMMARY:")
        print(f"Total commands: {len(results)}")
        print(f"Successful: {successful}")
        print(f"Failed: {failed}")

        if failed > 0:
            print("\nFailed commands:")
            for i, command, success, output in results:
                if not success:
                    print(f"  {i}. {command}")
                    if output:
                        print(f"     Error: {output}")

def main():
    if len(sys.argv) < 2:
        print("Usage: python encrypted_command_executor.py <commands_file> [--server-url <url>] [--offline]")
        sys.exit(1)

    filename = sys.argv[1]
    server_url = None
