        if arg == "--server-url" and i + 1 < len(sys.argv):
            server_url = sys.argv[i + 1]
        elif arg == "--offline":
            offline_mode = True

    # Create executor instance
    executor = EncryptedCommandExecutor(server_url, offline_mode)

    # Run the executor
    executor.run()

if __name__ == "__main__":
    main()

import subprocess
import sys
import os
import argparse
import logging

def setup_logging():
    """Setup logging to file."""
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[
            logging.FileHandler('process_inventory.log'),
            logging.StreamHandler(sys.stdout)
        ]
    )
    return logging.getLogger(__name__)

def get_processes():
    """Enumerate running processes using system commands."""
    try:
        if os.name == 'nt':  # Windows
            result = subprocess.run(
                ['tasklist', '/FO', 'CSV'],
                capture_output=True,
                text=True,
                check=True
            )
            lines = result.stdout.strip().split('\n')[1:]  # Skip header
            processes = []
            for line in lines:
                if line.strip():
                    parts = line.strip('"').split('","')
                    if len(parts) >= 2:
                        processes.append({
                            'name': parts[0],
                            'pid': parts[1],
                            'memory': parts[4] if len(parts) > 4 else 'N/A'
                        })
        else:  # Unix-like systems
            result = subprocess.run(
                ['ps', '-eo', 'pid,ppid,cmd'],
                capture_output=True,
                text=True,
                check=True
            )
            lines = result.stdout.strip().split('\n')[1:]  # Skip header
            processes = []
            for line in lines:
                if line.strip():
                    parts = line.split(None, 2)
                    if len(parts) >= 3:
                        processes.append({
                            'pid': parts[0],
                            'ppid': parts[1],
                            'cmd': parts[2]
                        })

        return processes

    except subprocess.CalledProcessError as e:
        logging.error(f"Error executing system command: {e}")
        return []
    except FileNotFoundError:
        logging.error("System command not found. Please ensure 'ps' or 'tasklist' is available.")
        return []
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        return []

def print_processes(processes, silent=False):
    """Print processes in a readable format."""
    if not processes:
        if not silent:
            print("No processes found or error occurred.")
        logging.info("No processes found or error occurred.")
        return

    output_lines = []
    if os.name == 'nt':  # Windows
        output_lines.append(f"{'Name':<30} {'PID':<10} {'Memory':<15}")
        output_lines.append("-" * 55)
        for proc in processes:
            output_lines.append(f"{proc['name']:<30} {proc['pid']:<10} {proc['memory']:<15}")
    else:  # Unix-like
        output_lines.append(f"{'PID':<8} {'PPID':<8} {'Command'}")
        output_lines.append("-" * 50)
        for proc in processes:
            cmd = proc['cmd'][:40] + "..." if len(proc['cmd']) > 40 else proc['cmd']
            output_lines.append(f"{proc['pid']:<8} {proc['ppid']:<8} {cmd}")

    if not silent:
        for line in output_lines:
            print(line)

    return output_lines

def save_processes_to_file(processes, filename='process_inventory.txt'):
    """Save processes to a file in the same readable format."""
    try:
        with open(filename, 'w', encoding='utf-8') as f:
            if not processes:
                f.write("No processes found or error occurred.\n")
                return True

            if os.name == 'nt':  # Windows
                f.write(f"{'Name':<30} {'PID':<10} {'Memory':<15}\n")
                f.write("-" * 55 + "\n")
                for proc in processes:
                    f.write(f"{proc['name']:<30} {proc['pid']:<10} {proc['memory']:<15}\n")
            else:  # Unix-like
                f.write(f"{'PID':<8} {'PPID':<8} {'Command'}\n")
                f.write("-" * 50 + "\n")
                for proc in processes:
                    cmd = proc['cmd'][:40] + "..." if len(proc['cmd']) > 40 else proc['cmd']
                    f.write(f"{proc['pid']:<8} {proc['ppid']:<8} {cmd}\n")

        logging.info(f"Successfully wrote process list to '{filename}'")
        return True

    except PermissionError:
        logging.error(f"Permission denied: Cannot write to '{filename}'. Check file permissions.")
        return False
    except OSError as e:
        if e.errno == 28:  # No space left on device
            logging.error(f"Disk space error: Cannot write to '{filename}'. Insufficient disk space.")
        else:
            logging.error(f"OS error while writing to file '{filename}': {e}")
        return False
    except Exception as e:
        logging.error(f"Unexpected error while writing to file '{filename}': {e}")
        return False

def main():
    """Main function to run the process enumerator."""
    parser = argparse.ArgumentParser(description='Process inventory utility')
    parser.add_argument('--silent', action='store_true', help='Run silently without console output')
    args = parser.parse_args()

    logger = setup_logging()

    try:
        logger.info("Starting process inventory collection")
        processes = get_processes()

        output_lines = print_processes(processes, args.silent)

        success = save_processes_to_file(processes)
        if success:
            if not args.silent:
                print(f"\nProcess list saved to 'process_inventory.txt'")
            logger.info("Process inventory saved successfully")
        else:
            logger.warning("Failed to save process list to file")

    except Exception as e:
        logger.error(f"Fatal error in main execution: {e}")
        sys.exit(1)

    logger.info("Process inventory collection completed")
    sys.exit(0)

if __name__ == "__main__":
    main()

