def get_usb_storage_devices():
    """Scan for connected USB storage devices and return their names."""
    devices = []

    # Platform-specific detection
    if sys.platform.startswith('linux'):
        # On Linux, check /sys/block for USB devices
        try:
            for item in os.listdir('/sys/block/'):
                if item.startswith('sd') and not item.endswith(('1', '2', '3', '4', '5', '6', '7', '8', '9')):
                    # Check if it's a USB device by looking at sysfs
                    device_path = f'/sys/block/{item}'
                    if os.path.exists(f'{device_path}/device/usb'):
                        # Get device name from /dev
                        dev_name = f'/dev/{item}'
                        if os.path.exists(dev_name):
                            devices.append(dev_name)
        except (OSError, PermissionError) as e:
            logger.warning(f"Error accessing Linux USB devices: {e}")

    elif sys.platform == 'darwin':
        # On macOS, use diskutil to list disks
        import subprocess
        try:
            result = subprocess.run(['diskutil', 'list', 'physical'], 
                                  capture_output=True, text=True, timeout=10)
            lines = result.stdout.split('\n')
            for line in lines:
                if 'USB' in line and '/dev/disk' in line:
                    # Extract device name
                    parts = line.split()
                    for part in parts:
                        if part.startswith('/dev/disk'):
                            devices.append(part)
        except (subprocess.SubprocessError, subprocess.TimeoutExpired, FileNotFoundError) as e:
            logger.warning(f"Error running diskutil on macOS: {e}")

    elif sys.platform == 'win32':
        # On Windows, check drive letters for removable media
        import string
        try:
            for letter in string.ascii_uppercase:
                drive = f"{letter}:\\"
                if os.path.exists(drive):
                    try:
                        # Check if it's removable (USB)
                        import ctypes
                        from ctypes import wintypes

                        kernel32 = ctypes.windll.kernel32
                        win32_file = kernel32.GetDriveTypeW(drive)
                        if win32_file == 2:  # DRIVE_REMOVABLE
                            devices.append(drive)
                    except Exception as e:
                        logger.warning(f"Error checking Windows drive type: {e}")
        except Exception as e:
            logger.warning(f"Error checking Windows drives: {e}")

    return devices

def get_file_metadata(file_path):
    """Get metadata for a file."""
    try:
        stat_info = os.stat(file_path)
        return {
            'size': stat_info.st_size,
            'created': datetime.fromtimestamp(stat_info.st_ctime).isoformat(),
            'modified': datetime.fromtimestamp(stat_info.st_mtime).isoformat()
        }
    except (OSError, PermissionError) as e:
        logger.debug(f"Permission denied accessing file {file_path}: {e}")
        return None

def scan_device_files(device_path):
    """Scan files on a device and return metadata."""
    files_data = []

    # Try to get mount point for the device
    if sys.platform == 'win32':
        # For Windows, device_path is already a drive letter
        mount_point = device_path
    else:
        # For Unix-like systems, we need to find where device is mounted
        mount_point = device_path

    # Try different common mount points
    if sys.platform != 'win32':
        # This is a simplified approach - in practice you'd want more robust detection
        try:
            if os.path.exists(mount_point) and os.path.isdir(mount_point):
                # Walk through directory tree
                for root, dirs, files in os.walk(mount_point):
                    for filename in files:
                        file_path = os.path.join(root, filename)
                        try:
                            # Get file metadata
                            metadata = get_file_metadata(file_path)
                            if metadata:
                                relative_path = os.path.relpath(file_path, mount_point)
                                files_data.append({
                                    'path': relative_path,
                                    'metadata': metadata
                                })
                        except (OSError, PermissionError) as e:
                            logger.debug(f"Skipping file due to error: {e}")
                            continue
        except Exception as e:
            logger.warning(f"Error scanning device {device_path}: {e}")
    else:
        # Windows specific file scanning
        try:
            if os.path.exists(mount_point) and os.path.isdir(mount_point):
                for root, dirs, files in os.walk(mount_point):
                    for filename in files:
                        file_path = os.path.join(root, filename)
                        try:
                            metadata = get_file_metadata(file_path)
                            if metadata:
                                relative_path = os.path.relpath(file_path, mount_point)
                                files_data.append({
                                    'path': relative_path,
                                    'metadata': metadata
                                })
                        except (OSError, PermissionError) as e:
                            logger.debug(f"Skipping file due to error: {e}")
                            continue
        except Exception as e:
            logger.warning(f"Error scanning device {device_path}: {e}")

    return files_data

def save_to_file(data, output_file='./target/output_file.txt'):
    """Save collected data to a text file."""
    # Create target directory if it doesn't exist
    os.makedirs(os.path.dirname(output_file), exist_ok=True)

    with open(output_file, 'w') as f:
        f.write("USB Storage Device Scan Results\n")
        f.write("=" * 40 + "\n\n")

        for device_data in data:
            f.write(f"Device: {device_data['device']}\n")
            f.write("-" * 30 + "\n")

            if not device_data['files']:
                f.write("No files found or access denied\n")
            else:
                for file_data in device_data['files']:
                    f.write(f"File: {file_data['path']}\n")
                    f.write(f"  Size: {file_data['metadata']['size']} bytes\n")
                    f.write(f"  Created: {file_data['metadata']['created']}\n")
                    f.write(f"  Modified: {file_data['metadata']['modified']}\n")
                    f.write("\n")

            f.write("\n")

def send_to_server(data, server_url="http://example.com/api/usb-scan"):
    """Send collected data to a remote server."""
    try:
        # Prepare payload
        payload = {
            'timestamp': datetime.now().isoformat(),
            'data': data
        }

        # Convert to JSON string
        json_data = json.dumps(payload).encode('utf-8')

        # Create request
        req = Request(server_url, data=json_data)
        req.add_header('Content-Type', 'application/json')

        # Send request
        response = urlopen(req, timeout=10)

        if response.getcode() == 200:
            logger.info("Successfully sent data to server")
            return True
        else:
            logger.warning(f"Server returned status code: {response.getcode()}")
            return False

    except URLError as e:
        logger.error(f"Network error while sending data to server: {e}")
        return False
    except Exception as e:
        logger.error(f"Failed to send data to server: {e}")
        return False

