import sys
import os
from datetime import datetime

class AppendUtility:
    def __init__(self):
        self.log_file = 'infect_log.txt'
        self.dry_run = False
        self.summary_only = False
        self.verbose = True

    def append_to_file(self, filepath, data):
        """Append data to specified file."""
        try:
            with open(filepath, 'a') as f:
                f.write(data)
            return True
        except Exception as e:
            raise IOError(f"Error appending to file '{filepath}': {e}")

    def log_append_operation(self, append_data, payload_size, file_path):
        """Log append operation to infect_log.txt."""
        try:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            log_entry = f"{timestamp},{append_data},{payload_size},{file_path}\n"
            with open(self.log_file, 'a') as log_file:
                log_file.write(log_entry)
            return True
        except Exception as e:
            raise IOError(f"Error writing to log file '{self.log_file}': {e}")

    def process_arguments(self):
        """Parse command line arguments."""
        if len(sys.argv) < 3:
            self.print_usage()
            sys.exit(1)

        self.filepath = sys.argv[1]
        self.data = sys.argv[2]

        # Parse flags
        self.dry_run = '--dry-run' in sys.argv
        self.summary_only = '--summary-only' in sys.argv
        self.verbose = not self.summary_only

        # Validate file path
        if not os.path.exists(os.path.dirname(self.filepath)) and os.path.dirname(self.filepath):
            raise IOError(f"Directory does not exist: {os.path.dirname(self.filepath)}")

    def print_usage(self):
        """Print usage information."""
        print("Usage: python append_util.py <file_path> <data> [--dry-run] [--summary-only]", file=sys.stderr)
        print("  --dry-run     Simulate append operation without making changes")
        print("  --summary-only Suppress detailed output, show only summary")

    def run(self):
        """Main execution method."""
        try:
            self.process_arguments()

            if self.dry_run:
                if self.verbose:
                    print("Dry run mode enabled - no changes will be made")

            # Calculate payload size
            payload_size = len(self.data.encode('utf-8'))

            # Perform append operation if not in dry run mode
            if not self.dry_run:
                self.append_to_file(self.filepath, self.data)
                if self.verbose:
                    print(f"Data appended successfully to {self.filepath}")

            # Log the operation if not in dry run mode
            if not self.dry_run:
                self.log_append_operation(self.data, payload_size, self.filepath)

            # Print summary
            if self.verbose:
                print(f"Summary: {payload_size} bytes appended to {self.filepath}")
                if not self.dry_run:
                    print(f"Log entry written to {self.log_file}")
            else:
                print(f"Appended {payload_size} bytes to {self.filepath}")

        except IOError as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)
        except Exception as e:
            print(f"Unexpected error: {e}", file=sys.stderr)
            sys.exit(1)

def main():
    utility = AppendUtility()
    utility.run()

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import subprocess
import sys
import platform
import os
import argparse
import logging
from datetime import datetime

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.StreamHandler(sys.stdout),
        logging.FileHandler('software_enumeration.log')
    ]
)
logger = logging.getLogger(__name__)

def run_command(cmd):
    """Execute a command and return its output."""
    logger.debug(f"Executing command: {cmd}")
    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        if result.returncode == 0:
            logger.debug(f"Command executed successfully: {cmd}")
            return result.stdout.strip()
        else:
            logger.warning(f"Command failed with return code {result.returncode}: {cmd}")
            return None
    except subprocess.TimeoutExpired:
        logger.error(f"Command timed out: {cmd}")
        return None
    except Exception as e:
        logger.error(f"Exception while executing command {cmd}: {e}")
        return None

def enumerate_packages_debian():
    """Enumerate packages on Debian/Ubuntu systems."""
    packages = set()

    # apt list --installed
    output = run_command("apt list --installed 2>/dev/null")
    if output:
        for line in output.split('\n'):
            if '/' in line and not line.startswith('Listing'):
                pkg = line.split('/')[0]
                packages.add(pkg)

    # dpkg -l
    output = run_command("dpkg -l 2>/dev/null | grep '^ii'")
    if output:
        for line in output.split('\n'):
            if line.startswith('ii'):
                parts = line.split()
                if len(parts) >= 2:
                    packages.add(parts[1])

    logger.info(f"Found {len(packages)} packages on Debian/Ubuntu system")
    return sorted(packages)

def enumerate_packages_redhat():
    """Enumerate packages on RedHat/CentOS/Fedora systems."""
    packages = set()

    # rpm -qa
    output = run_command("rpm -qa 2>/dev/null")
    if output:
        for line in output.split('\n'):
            if line.strip():
                packages.add(line.strip())

    logger.info(f"Found {len(packages)} packages on RedHat/CentOS/Fedora system")
    return sorted(packages)

def enumerate_packages_arch():
    """Enumerate packages on Arch Linux systems."""
    packages = set()

    # pacman -Q
    output = run_command("pacman -Q 2>/dev/null")
    if output:
        for line in output.split('\n'):
            if line.strip():
                parts = line.split()
                if len(parts) >= 1:
                    packages.add(parts[0])

    logger.info(f"Found {len(packages)} packages on Arch system")
    return sorted(packages)

def enumerate_packages_macos():
    """Enumerate packages on macOS systems."""
    packages = set()

    # brew list
    output = run_command("brew list 2>/dev/null")
    if output:
        for line in output.split('\n'):
            if line.strip():
                packages.add(line.strip())

    # pkgutil --packages
    output = run_command("pkgutil --packages 2>/dev/null")
    if output:
        for line in output.split('\n'):
            if line.strip():
                packages.add(line.strip())

    logger.info(f"Found {len(packages)} packages on macOS system")
    return sorted(packages)

def enumerate_packages_windows():
    """Enumerate packages on Windows systems."""
    packages = set()

    # wmic product get name
    output = run_command("wmic product get name 2>nul")
    if output:
        lines = output.split('\n')
        if len(lines) > 1:
            for line in lines[1:]:
                if line.strip():
                    packages.add(line.strip())

    # Get-ItemProperty HKLM:SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*
    output = run_command("powershell \"Get-ItemProperty HKLM:SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\* | Where-Object {$_.DisplayName} | Select-Object -ExpandProperty DisplayName\" 2>$null")
    if output:
        for line in output.split('\n'):
            if line.strip():
                packages.add(line.strip())

    logger.info(f"Found {len(packages)} packages on Windows system")
    return sorted(packages)

def enumerate_packages_generic():
    """Fallback method to enumerate packages."""
    packages = set()

    # Try various common package managers
    commands = [
        "pip list --format=freeze 2>/dev/null",
        "conda list 2>/dev/null",
        "gem list 2>/dev/null",
        "npm list -g --depth=0 2>/dev/null"
    ]

    for cmd in commands:
        output = run_command(cmd)
        if output:
            for line in output.split('\n'):
                if line.strip() and not line.startswith('Package') and not line.startswith('├──'):
                    packages.add(line.strip())

    logger.info(f"Found {len(packages)} packages using generic method")
    return sorted(packages)

def write_to_file(packages, filename="av_inventory.txt"):
    """Write packages to a file."""
    logger.info(f"Writing {len(packages)} packages to file: {filename}")
    try:
        with open(filename, 'w', encoding='utf-8') as f:
            for pkg in packages:
                f.write(f"{pkg}\n")
        logger.info(f"Successfully wrote {len(packages)} packages to {filename}")
        return True
    except PermissionError:
        logger.error(f"Permission denied: Cannot write to {filename}")
        return False
    except OSError as e:
        logger.error(f"OS error while writing to file {filename}: {e}")
        return False
    except Exception as e:
        logger.error(f"Unexpected error while writing to file {filename}: {e}")
        return False

def main():
    """Main function to enumerate installed software."""
    parser = argparse.ArgumentParser(description='Enumerate installed software on the system')
    parser.add_argument('-v', '--verbose', action='store_true', help='Enable verbose logging')
    parser.add_argument('-o', '--output', default='av_inventory.txt', help='Output file path')
    parser.add_argument('--no-file', action='store_true', help='Skip writing to file')

    args = parser.parse_args()

    if args.verbose:
        logger.setLevel(logging.DEBUG)

    logger.info("Starting software enumeration process")
    logger.info(f"Output file: {args.output}")

    system = platform.system().lower()
    logger.info(f"Detected system: {system}")

    try:
        if system == "linux":
            # Determine distribution
            distro = ""
            if os.path.exists("/etc/os-release"):
                with open("/etc/os-release", "r") as f:
                    content = f.read()
                    if "ubuntu" in content.lower() or "debian" in content.lower():
                        distro = "debian"
                    elif "redhat" in content.lower() or "centos" in content.lower() or "fedora" in content.lower():
                        distro = "redhat"
                    elif "arch" in content.lower():
                        distro = "arch"

            if distro == "debian":
                packages = enumerate_packages_debian()
            elif distro == "redhat":
                packages = enumerate_packages_redhat()
            elif distro == "arch":
                packages = enumerate_packages_arch()
            else:
                # Generic Linux approach
                packages = enumerate_packages_generic()

        elif system == "darwin":  # macOS
            packages = enumerate_packages_macos()
        elif system == "windows":
            packages = enumerate_packages_windows()
        else:
            # Fallback for unknown systems
            packages = enumerate_packages_generic()

        if packages:
            logger.info(f"Found {len(packages)} installed packages")
            print(f"Found {len(packages)} installed packages:")
            print("-" * 30)
            for pkg in packages:
                print(pkg)

            # Write to file if requested
            if not args.no_file:
                if write_to_file(packages, args.output):
                    print(f"\nPackage list written to {args.output}")
                else:
                    print(f"\nFailed to write package list to {args.output}")
            else:
                logger.info("File writing skipped by user request")
        else:
            logger.warning("No packages found or unable to enumerate packages")
            print("No packages found or unable to enumerate packages.")

    except KeyboardInterrupt:
        logger.info("Enumeration interrupted by user")
        print("\nEnumeration interrupted by user.")
        sys.exit(1)
    except Exception as e:
        logger.error(f"An unexpected error occurred during enumeration: {e}")
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

    logger.info("Software enumeration process completed")

if __name__ == "__main__":
    main()
